import sys, json
from typing import List

class Solution:
    def shortestSuperstring(self, words: List[str]) -> str:
        n = len(words)
        overlap = [[0] * n for _ in range(n)]

        for i, a in enumerate(words):
            for j, b in enumerate(words):
                max_k = min(len(a), len(b))
                for k in range(max_k, 0, -1):
                    if a[-k:] == b[:k]:
                        overlap[i][j] = k
                        break

        states = 1 << n
        dp = [[-1] * n for _ in range(states)]
        parent = [[-1] * n for _ in range(states)]

        for i in range(n):
            dp[1 << i][i] = 0

        for mask in range(1, states):
            for last in range(n):
                if (mask & (1 << last)) == 0:
                    continue
                prev_mask = mask ^ (1 << last)
                if prev_mask == 0:
                    continue

                best_overlap = -1
                best_prev = -1
                for prev in range(n):
                    if (prev_mask & (1 << prev)) == 0:
                        continue
                    value = dp[prev_mask][prev] + overlap[prev][last]
                    if value > best_overlap or (
                        value == best_overlap and prev > best_prev
                    ):
                        best_overlap = value
                        best_prev = prev

                dp[mask][last] = best_overlap
                parent[mask][last] = best_prev

        mask = states - 1
        last = max(range(n), key=lambda i: (dp[mask][i], i))

        order = []
        while last != -1:
            order.append(last)
            previous = parent[mask][last]
            mask ^= 1 << last
            last = previous

        order.reverse()

        result = words[order[0]]
        for i in range(1, len(order)):
            a = order[i - 1]
            b = order[i]
            result += words[b][overlap[a][b]:]

        return result

