#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int overlap_len(const char *a, const char *b) {
    int la = (int)strlen(a);
    int lb = (int)strlen(b);
    int max_k = la < lb ? la : lb;

    for (int k = max_k; k >= 1; --k) {
        int ok = 1;
        for (int p = 0; p < k; ++p) {
            if (a[la - k + p] != b[p]) {
                ok = 0;
                break;
            }
        }
        if (ok) return k;
    }
    return 0;
}

char *shortestSuperstring(char **words, int wordsSize) {
    int n = wordsSize;
    int states = 1 << n;

    int *overlap = (int *)calloc((size_t)n * n, sizeof(int));
    int *dp = (int *)malloc((size_t)states * n * sizeof(int));
    int *parent = (int *)malloc((size_t)states * n * sizeof(int));

    for (int mask = 0; mask < states; ++mask) {
        for (int i = 0; i < n; ++i) {
            dp[mask * n + i] = -1;
            parent[mask * n + i] = -1;
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            overlap[i * n + j] = overlap_len(words[i], words[j]);
        }
        dp[(1 << i) * n + i] = 0;
    }

    for (int mask = 1; mask < states; ++mask) {
        for (int last = 0; last < n; ++last) {
            if ((mask & (1 << last)) == 0) continue;

            int prevMask = mask ^ (1 << last);
            if (prevMask == 0) continue;

            int bestOverlap = -1;
            int bestPrev = -1;

            for (int prev = 0; prev < n; ++prev) {
                if ((prevMask & (1 << prev)) == 0) continue;

                int value = dp[prevMask * n + prev] + overlap[prev * n + last];
                if (value > bestOverlap ||
                    (value == bestOverlap && prev > bestPrev)) {
                    bestOverlap = value;
                    bestPrev = prev;
                }
            }

            dp[mask * n + last] = bestOverlap;
            parent[mask * n + last] = bestPrev;
        }
    }

    int mask = states - 1;
    int last = 0;
    for (int i = 1; i < n; ++i) {
        int a = dp[mask * n + i];
        int b = dp[mask * n + last];
        if (a > b || (a == b && i > last)) last = i;
    }

    int *order = (int *)malloc((size_t)n * sizeof(int));
    int pos = n - 1;

    while (last != -1) {
        order[pos--] = last;
        int previous = parent[mask * n + last];
        mask ^= 1 << last;
        last = previous;
    }

    int capacity = 256;
    char *result = (char *)malloc((size_t)capacity);
    result[0] = '\0';

    for (int k = 0; k < n; ++k) {
        int idx = order[k];
        const char *part = words[idx];
        if (k > 0) {
            int prev = order[k - 1];
            part += overlap[prev * n + idx];
        }

        int need = (int)strlen(result) + (int)strlen(part) + 1;
        if (need > capacity) {
            while (capacity < need) capacity *= 2;
            result = (char *)realloc(result, (size_t)capacity);
        }
        strcat(result, part);
    }

    free(overlap);
    free(dp);
    free(parent);
    free(order);
    return result;
}

static char **parse_words(const char *line, int *count) {
    int capacity = 16;
    int size = 0;
    char **words = (char **)malloc((size_t)capacity * sizeof(char *));

    for (const char *p = line; *p; ++p) {
        if (*p != '"') continue;

        const char *start = ++p;
        while (*p && *p != '"') ++p;
        int len = (int)(p - start);

        if (size == capacity) {
            capacity *= 2;
            words = (char **)realloc(words, (size_t)capacity * sizeof(char *));
        }

        words[size] = (char *)malloc((size_t)len + 1);
        memcpy(words[size], start, (size_t)len);
        words[size][len] = '\0';
        ++size;

        if (!*p) break;
    }

    *count = size;
    return words;
}

int main(void) {
    char line[4096];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    int wordsSize = 0;
    char **words = parse_words(line, &wordsSize);

    char *result = shortestSuperstring(words, wordsSize);
    printf("\"%s\"\n", result);

    free(result);
    for (int i = 0; i < wordsSize; ++i) free(words[i]);
    free(words);
    return 0;
}

