        vector<vector<int>> overlap(n, vector<int>(n, 0));

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int maxK = min(words[i].size(), words[j].size());
                for (int k = maxK; k >= 1; --k) {
                    if (words[i].compare(words[i].size() - k, k, words[j], 0, k) == 0) {
