                        break;
                    }
                }
            }
        }

        int states = 1 << n;
        vector<vector<int>> dp(states, vector<int>(n, -1));
        vector<vector<int>> parent(states, vector<int>(n, -1));

        for (int i = 0; i < n; ++i) dp[1 << i][i] = 0;

        for (int mask = 1; mask < states; ++mask) {
            for (int last = 0; last < n; ++last) {
                if ((mask & (1 << last)) == 0) continue;
                int prevMask = mask ^ (1 << last);
                if (prevMask == 0) continue;

                int bestOverlap = -1;
                int bestPrev = -1;
                for (int prev = 0; prev < n; ++prev) {
                    if ((prevMask & (1 << prev)) == 0) continue;
                    int value = dp[prevMask][prev] + overlap[prev][last];
                    if (value > bestOverlap ||
                        (value == bestOverlap && prev > bestPrev)) {
                        bestOverlap = value;
                        bestPrev = prev;
                    }
                }
                dp[mask][last] = bestOverlap;
                parent[mask][last] = bestPrev;
            }
        }

        int mask = states - 1;
        int last = 0;
        for (int i = 1; i < n; ++i) {
            if (dp[mask][i] > dp[mask][last] ||
                (dp[mask][i] == dp[mask][last] && i > last)) {
                last = i;
            }
        }

        vector<int> order;
        while (last != -1) {
            order.push_back(last);
            int previous = parent[mask][last];
            mask ^= 1 << last;
            last = previous;
        }
        reverse(order.begin(), order.end());

        string result = words[order[0]];
        for (int i = 1; i < (int)order.size(); ++i) {
            int a = order[i - 1];
            int b = order[i];
            result += words[b].substr(overlap[a][b]);
        }
        return result;
    }
};

static vector<string> parseWords(const string& line) {
    vector<string> words;
    for (size_t i = 0; i < line.size();) {
        if (line[i] != '"') {
            ++i;
            continue;
        }
        size_t j = i + 1;
        while (j < line.size() && line[j] != '"') ++j;
        words.push_back(line.substr(i + 1, j - i - 1));
        i = (j == line.size() ? j : j + 1);
    }
    return words;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    getline(cin, line);
    vector<string> words = parseWords(line);
    string result = Solution().shortestSuperstring(words);
    cout << '"' << result << '"' << '\n';
    return 0;
}

