class Solution {
    public String shortestSuperstring(String[] words) {
        int n = words.length;
        int[][] overlap = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int max = Math.min(words[i].length(), words[j].length());
                for (int k = max; k >= 1; k--) {
                    if (words[i].regionMatches(words[i].length() - k, words[j], 0, k)) {
                        overlap[i][j] = k;
                        break;
                    }
                }
            }
        }

        int states = 1 << n;
        int[][] dp = new int[states][n];
        int[][] parent = new int[states][n];
        for (int[] row : dp) Arrays.fill(row, -1);
        for (int[] row : parent) Arrays.fill(row, -1);

        for (int i = 0; i < n; i++) dp[1 << i][i] = 0;

        for (int mask = 1; mask < states; mask++) {
            for (int last = 0; last < n; last++) {
                if ((mask & (1 << last)) == 0) continue;
                int prevMask = mask ^ (1 << last);
                if (prevMask == 0) continue;

                int bestOverlap = -1;
                int bestPrev = -1;
                for (int prev = 0; prev < n; prev++) {
                    if ((prevMask & (1 << prev)) == 0) continue;
                    int value = dp[prevMask][prev] + overlap[prev][last];
                    if (value > bestOverlap || (value == bestOverlap && prev > bestPrev)) {
                        bestOverlap = value;
                        bestPrev = prev;
                    }
                }
                dp[mask][last] = bestOverlap;
                parent[mask][last] = bestPrev;
            }
        }

        int mask = states - 1;
        int last = 0;
        for (int i = 1; i < n; i++) {
            if (dp[mask][i] > dp[mask][last] ||
                (dp[mask][i] == dp[mask][last] && i > last)) {
                last = i;
            }
        }

        int[] order = new int[n];
        int pos = n - 1;
        while (last != -1) {
            order[pos--] = last;
            int previous = parent[mask][last];
            mask ^= 1 << last;
            last = previous;
        }

        StringBuilder result = new StringBuilder();
        result.append(words[order[0]]);
        for (int i = 1; i < n; i++) {
            int a = order[i - 1];
            int b = order[i];
            result.append(words[b].substring(overlap[a][b]));
        }
        return result.toString();
    }
}

public class Main {
    static List<String> parseWords(String line) {
        List<String> words = new ArrayList<>();
        int i = 0;
        while (i < line.length()) {
            if (line.charAt(i) != '"') {
                i++;
                continue;
            }
            int j = i + 1;
            while (j < line.length() && line.charAt(j) != '"') j++;
            words.add(line.substring(i + 1, j));
            i = j + 1;
        }
        return words;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        List<String> list = parseWords(line);
        String[] words = list.toArray(new String[0]);
        String result = new Solution().shortestSuperstring(words);
        System.out.println("\"" + result + "\"");
    }
}

